-- Synthetic operational submissions only; enclosing policy harness rolls all fixtures back.
RESET ROLE;
SELECT ok(NOT has_table_privilege('anon','firstten_private.founding_partner_submissions','SELECT,INSERT,UPDATE,DELETE'),'anonymous has no operational table privilege');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.founding_partner_submissions','SELECT,INSERT,UPDATE,DELETE'),'signed users cannot inspect operational submissions');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.founding_partner_submissions','SELECT,INSERT,UPDATE,DELETE'),'service role has no broad direct table access');
SELECT ok(NOT has_function_privilege('anon','public.record_founding_partner(text,text,text,text,text)','EXECUTE'),'anonymous cannot bypass server validation');
SELECT ok(NOT has_function_privilege('authenticated','public.record_founding_partner(text,text,text,text,text)','EXECUTE'),'signed users cannot bypass public server form');
SELECT ok(has_function_privilege('service_role','public.record_founding_partner(text,text,text,text,text)','EXECUTE'),'only service path has RPC execution');
SELECT ok((SELECT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] FROM pg_proc WHERE oid='public.record_founding_partner(text,text,text,text,text)'::regprocedure),'narrow operation uses fixed definer search path');
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.record_founding_partner('blocked@example.test','Fixture','interest','',NULL)$$,'42501','permission denied for function record_founding_partner','anonymous invocation is denied by PostgreSQL');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.record_founding_partner('blocked@example.test','Fixture','interest','',NULL)$$,'42501','permission denied for function record_founding_partner','signed browser invocation is denied by PostgreSQL');
SET LOCAL ROLE service_role;
SELECT is(public.record_founding_partner('teacher@example.test','Fictional school','interest','',NULL),'{"ok":true}'::jsonb,'bounded interest stores with no PII response');
SELECT is(public.record_founding_partner('TEACHER@example.test','Fictional school','feedback','Fixture feedback',NULL),'{"ok":true}'::jsonb,'case normalized email shares throttle');
SELECT is(public.record_founding_partner('teacher@example.test','Fictional school','interest','',NULL),'{"ok":true}'::jsonb,'third email request is allowed');
SELECT is(public.record_founding_partner('teacher@example.test','Fictional school','interest','',NULL)->>'code','RATE_LIMITED','fourth normalized email request is throttled');
SELECT is(public.record_founding_partner('bad','Fictional school','interest','',NULL)->>'code','INVALID','database rejects malformed email');
SELECT is(public.record_founding_partner('a@example.test','Fictional school','feedback','',NULL)->>'code','INVALID','database requires actual feedback text');
SELECT is(public.record_founding_partner('a@example.test','Fictional school','interest',repeat('x',2001),NULL)->>'code','INVALID','database limits stored note length');
SELECT is(public.record_founding_partner('a@example.test','Fictional school','interest','','raw-ip')->>'code','INVALID','database never accepts raw IP in hash field');
RESET ROLE;
SELECT is((SELECT count(*) FROM firstten_private.founding_partner_submissions),3::bigint,'rejected records are not stored');
UPDATE firstten_private.founding_partner_submissions SET created_at=clock_timestamp()-interval '2 hours';
SET LOCAL ROLE service_role;
SELECT is(public.record_founding_partner('teacher@example.test','Fictional school','interest','',NULL),'{"ok":true}'::jsonb,'rolling email allowance recovers after one hour');
DO $$ DECLARE i integer; j integer; response jsonb; BEGIN FOR i IN 1..45 LOOP FOR j IN 1..3 LOOP response:=public.record_founding_partner('classroom'||i||'@example.test','Fictional classroom','interest','',repeat('a',64)); IF response->>'ok'<>'true' THEN RAISE EXCEPTION 'Shared classroom fixture was unexpectedly blocked'; END IF; END LOOP; END LOOP; END $$;
RESET ROLE;
SELECT is((SELECT count(*) FROM firstten_private.founding_partner_submissions WHERE ip_hash=repeat('a',64)),135::bigint,'45 classroom attendees can each submit three times on shared WiFi');
INSERT INTO firstten_private.founding_partner_submissions(email,school,kind,note,ip_hash) SELECT 'cap'||i||'@example.test','Fixture','interest','',repeat('a',64) FROM generate_series(1,15) i;
SET LOCAL ROLE service_role;
SELECT is(public.record_founding_partner('next@example.test','Fixture','interest','',repeat('a',64))->>'code','RATE_LIMITED','shared IP cap prevents unlimited unique emails');
RESET ROLE;
INSERT INTO firstten_private.founding_partner_submissions(email,school,kind,note) SELECT 'global'||i||'@example.test','Fixture','interest','' FROM generate_series(1,349) i;
SET LOCAL ROLE service_role;
SELECT is(public.record_founding_partner('global-next@example.test','Fixture','interest','',NULL)->>'code','RATE_LIMITED','global cap applies even without a platform IP');
RESET ROLE;
SELECT ok(NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='firstten_private' AND table_name='founding_partner_submissions' AND column_name IN ('user_id','project_id','interviews','answers','raw_ip')),'operational form stores no workspace or participant linkage');
